package dev.hrutvik.billing.credit;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Repository
public class CreditStore {
 private final JdbcTemplate jdbc; public CreditStore(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public Optional<StoredCredit> find(String tenantId,String idempotencyKey){return jdbc.query("""SELECT id,credit_number,invoice_id,currency,amount,reason,created_at,request_fingerprint FROM credit_notes WHERE tenant_id=? AND idempotency_key=?""",(rs,n)->new StoredCredit(rs.getObject("id",UUID.class),rs.getString("credit_number"),rs.getObject("invoice_id",UUID.class),rs.getString("currency"),rs.getBigDecimal("amount"),rs.getString("reason"),rs.getTimestamp("created_at").toInstant(),rs.getString("request_fingerprint")),tenantId,idempotencyKey).stream().findFirst();}
 public InvoiceBalance lockInvoice(String tenantId,UUID invoiceId){var invoice=jdbc.query("""SELECT id,currency,total FROM invoices WHERE id=? AND tenant_id=? AND status='FINALIZED' FOR UPDATE""",(rs,n)->new InvoiceBalance(rs.getObject("id",UUID.class),rs.getString("currency"),rs.getBigDecimal("total"),BigDecimal.ZERO),invoiceId,tenantId).stream().findFirst().orElseThrow(()->new IllegalArgumentException("finalized invoice not found"));BigDecimal credited=jdbc.queryForObject("SELECT COALESCE(SUM(amount),0) FROM credit_notes WHERE invoice_id=?",BigDecimal.class,invoiceId);return new InvoiceBalance(invoice.invoiceId(),invoice.currency(),invoice.invoiceTotal(),credited);}
 public void insert(UUID id,String number,String tenantId,UUID invoiceId,String currency,BigDecimal amount,String reason,String key,String fingerprint,Instant now){jdbc.update("""INSERT INTO credit_notes(id,credit_number,tenant_id,invoice_id,currency,amount,reason,idempotency_key,request_fingerprint,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)""",id,number,tenantId,invoiceId,currency,amount,reason,key,fingerprint,now);}
 public record StoredCredit(UUID id,String number,UUID invoiceId,String currency,BigDecimal amount,String reason,Instant createdAt,String fingerprint){CreditResponse response(){return new CreditResponse(id,number,invoiceId,currency,amount,reason,createdAt,true);}}
}
